//! One-time session tokens for the loopback endpoint.
//!
//! The token is the only credential a request to the endpoint carries besides
//! its origin headers (see `serve.rs`), and it plays AutoFirma's role: the
//! page learns an `idsession` at launch time (`afirma://websocket?…&idsession=`,
//! checked per message in `AfirmaWebSocketServerV4Sup.onMessage`) and must put
//! it in every message. Ours is generated by the *server* (a random, 128-bit,
//! alphanumeric id on the same `[a-z0-9]`/≤20 alphabet AutoFirma's own parser
//! enforces), handed to whoever opened us — out of band, exactly like the port
//! is — and consumed by its first request. A page that never learned it cannot
//! ask; a second request with the same id is a replay and gets refused.

use getrandom::fill;

/// The longest session id AutoFirma's protocol accepts: `MAX_ID_LENGTH = 20`
/// in `UrlParameters`, because it doubles as a file name. Ours is shorter —
/// 16 lower-case alphanumeric characters carry 128 bits of entropy and fit
/// the alphabet with room to spare.
const TOKEN_LEN: usize = 16;

const ALPHABET: &[u8] = b"abcdefghijklmnopqrstuvwxyz0123456789";

fn random_token() -> String {
    let mut bytes = [0u8; TOKEN_LEN];
    // getrandom's fill does not return until the OS entropy pool answers or
    // the process is killed for asking; neither can be handled better than by
    // letting it do its job.
    fill(&mut bytes).expect("the operating system's random source must answer");
    bytes
        .iter()
        .map(|b| ALPHABET[(*b as usize) % ALPHABET.len()] as char)
        .collect()
}

/// A small table of live session tokens. `take` consumes one, atomically: the
/// window between check and use is zero bytes of logic wide, which is the
/// only way a one-time token is actually one-time under a concurrent server.
#[derive(Debug)]
pub struct TokenStore {
    inner: std::sync::Mutex<Vec<String>>,
}

impl Default for TokenStore {
    fn default() -> Self {
        Self::new()
    }
}

impl TokenStore {
    pub fn new() -> Self {
        TokenStore {
            inner: std::sync::Mutex::new(Vec::new()),
        }
    }

    /// Creates a fresh session id and hands it to the caller (the CLI's
    /// stdout, or the loopback server's own owner). A poisoned lock — some
    // other connection panicked mid-update — means the table may hold
    // garbage, so minting from it is refused rather than trusted.
    pub fn issue(&self) -> String {
        let mut guard = self
            .inner
            .lock()
            .expect("the token table must not stay poisoned: a handler panicked while holding it");
        let token = random_token();
        guard.push(token.clone());
        token
    }

    /// True if `presented` is a live session id, consuming it. Comparison is
    /// exact string equality; the ids are not secret-after-use, so constant
    /// time buys nothing here — the table lookup itself does not leak whether
    /// an id exists beyond timing that scales with live sessions (at most a
    // handful).
    pub fn take(&self, presented: &str) -> bool {
        if presented.is_empty() || presented.len() > 20 {
            return false;
        }
        let mut guard = match self.inner.lock() {
            Ok(guard) => guard,
            // A poisoned table is an empty one for the purposes of granting
            // access: nothing in it can be trusted any more.
            Err(_) => return false,
        };
        if let Some(pos) = guard.iter().position(|t| t == presented) {
            guard.remove(pos);
            true
        } else {
            false
        }
    }

    pub fn len(&self) -> usize {
        self.inner.lock().map(|g| g.len()).unwrap_or(0)
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }
}
